private static String normalizeTheme(String theme) {
    if (theme.startsWith("@style/")) return theme.substring(7);
    if (theme.startsWith("@android:style/")) return theme.substring(15);
    int slash = theme.indexOf('/');
    if (slash != -1) return theme.substring(slash + 1);
    return theme;
}
```
